{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Bumetanide, the closest analogue sharing the phenoxy-sulfamoylbenzoic acid core, had absolute oral bioavailability of 90% in healthy subjects, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "In normal subjects, bumetanide 1 mg oral tablet gave absolute bioavailability of 0.86 ± 0.13, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Bumetanide bioavailability was 0.899 and 0.893 by AUC and urinary excretion methods after 1 mg oral versus IV, confirming near-complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bumetanide bioavailability in healthy volunteers was 59-89% (median 80%), consistently high across studies.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "BMS-187745, a highly polar phosphonic/sulfonic acid, had absolute oral bioavailability of only 2.6%, but it is structurally distant from the query and lacks the bumetanide-like scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue bumetanide has consistently high absolute oral bioavailability (69-95%) in humans, well above the 20% threshold. Although the query replaces the butylamino group with a pyrrolidine ring and the physicochemical prior is unfavorable, the strong experimental evidence from the close analogue outweighs the prior and supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "The effect of replacing bumetanide's butylamino group with a pyrrolidine ring on absorption and first-pass metabolism is not experimentally characterized.",
    "The physicochemical prior predicts poor permeability, but bumetanide demonstrates that this scaffold can still be well absorbed; actual permeability/transport data for the query are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

